92	  // Read each node's backup-storage content. This is the same read-only
93	  // `/storage/backup/content` call `listBackupsOn`/`backupSummary` make; we read
94	  // the FULL listing (no vmid filter) because orphan archives — whose vmid has no
95	  // Server — must be surfaced, and a vmid-filtered read can never see them.
96	  const nodes: NodeEnum[] = [];
97	  const entries: NodeArchive[] = [];
98	  let anyNodeUnreachable = false;
99	  for (const t of targets) {
100	    try {
101	      const items: any[] = await t.get(`/nodes/${t.pveNode}/storage/backup/content`, {
102	        content: "backup",
103	      });
104	      let count = 0;
105	      for (const raw of items ?? []) {
106	        if (typeof raw?.volid !== "string") continue;
107	        entries.push({
108	          nodeLabel: t.label,
109	          raw: {
110	            volid: raw.volid,
111	            vmid: typeof raw.vmid === "number" ? raw.vmid : undefined,
112	            ctime: typeof raw.ctime === "number" ? raw.ctime : undefined,
113	            size: typeof raw.size === "number" ? raw.size : undefined,
114	          },
