"use server";

/**
 * ADMIN-only actions for the free Minecraft product — a separate surface from
 * lib/actions-free-minecraft.ts (the customer-facing actions, which all resolve
 * "the caller's own server" via `requireUser()` + `userId`). Admins need to
 * operate on ANY server by id, so every export here re-checks `requireArea("fleet")`
 * itself (never trust the UI alone) and looks the row up by `id`, not by caller.
 *
 * `"use server"` means every export is a network-reachable endpoint.
 */
import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireArea } from "./rbac";
import { withServerSsh, exec, shellQuote } from "./ssh-exec";
import { getFreeServerStatus } from "./free-minecraft-control";
import type { SftpServer } from "./sftp";

type Result = { ok?: boolean; error?: string };

/** Same dedicated Docker host lib/actions-free-minecraft.ts talks to — a real
 *  Server row (hostname="freemc-host"), not a customer VPS. */
async function freemcHost(): Promise<SftpServer> {
  const host = await db.server.findFirst({
    where: { hostname: "freemc-host" },
    select: { id: true, rootPassword: true, rootPasswordEnc: true, sshPort: true, dedicatedIp: { select: { address: true } } },
  });
  if (!host) throw new Error("Free Minecraft host is not provisioned.");
  return host;
}

/** Lazy, on-demand live status for one server (running + player count) — the
 *  list page deliberately does NOT fetch this for every row on load (see
 *  app/admin/free-minecraft/page.tsx's header note); this backs a per-row
 *  "check status" button instead. */
export async function adminGetFreeMinecraftStatus(
  id: string
): Promise<{ ok: true; running: boolean; players: { online: number; max: number } | null } | { ok: false; error: string }> {
  await requireArea("fleet");
  const row = await db.freeMinecraftServer.findUnique({ where: { id }, select: { containerName: true } });
  if (!row) return { ok: false, error: "Server not found." };

  try {
    const host = await freemcHost();
    const status = await withServerSsh(host, (conn) => getFreeServerStatus(conn, row.containerName));
    return { ok: true, running: status.running, players: status.players };
  } catch (e) {
    console.error("[admin-freemc] status check failed:", e);
    return { ok: false, error: "Could not reach the free Minecraft host." };
  }
}

/**
 * Force a server's public listing off — a moderation lever for a listing that
 * needs to be pulled (abuse report, inappropriate tagline/description, etc.)
 * without deleting the server or touching its container.
 */
export async function adminUnpublishFreeMinecraftServer(id: string): Promise<Result> {
  const admin = await requireArea("fleet");
  const row = await db.freeMinecraftServer.findUnique({ where: { id }, select: { id: true, isPublic: true } });
  if (!row) return { error: "Server not found." };
  if (!row.isPublic) return { ok: true };

  await db.freeMinecraftServer.update({ where: { id }, data: { isPublic: false } });
  await db.auditLog.create({
    data: { userId: admin.id, action: "admin.freemc_unpublish", detail: id },
  });
  revalidatePath("/admin/free-minecraft");
  return { ok: true };
}

/**
 * Delete a stray/abandoned free server: `docker rm -f` its container + wipe its
 * data dir on freemc-host, then remove the DB row. Same cleanup shape as the
 * customer-facing `deleteFreeMinecraftServer` in lib/actions-free-minecraft.ts,
 * but admin-gated and looked up by `id` (any server), not by the caller's own
 * userId. The DB row is removed even if the SSH cleanup fails — a stuck row
 * that no longer resolves to a real container is worse than an orphaned
 * container directory an admin can still clean up by hand.
 */
export async function adminDeleteFreeMinecraftServer(id: string): Promise<Result> {
  const admin = await requireArea("fleet");
  const row = await db.freeMinecraftServer.findUnique({
    where: { id },
    select: { id: true, containerName: true, subdomain: true },
  });
  if (!row) return { error: "Server not found." };

  try {
    const host = await freemcHost();
    await withServerSsh(host, async (conn) => {
      await exec(conn, `docker rm -f ${shellQuote(row.containerName)}`, 30_000);
      await exec(conn, `rm -rf ${shellQuote(`/opt/freemc/servers/${row.id}`)}`, 15_000);
    });
  } catch (e) {
    console.error("[admin-freemc] delete cleanup failed (row is removed regardless):", e);
  }

  await db.freeMinecraftServer.delete({ where: { id } });
  await db.auditLog.create({
    data: { userId: admin.id, action: "admin.freemc_delete", detail: `${id} (${row.subdomain})` },
  });
  revalidatePath("/admin/free-minecraft");
  return { ok: true };
}

"use client";

import { useState, useTransition } from "react";
import {
  adminGetFreeMinecraftStatus,
  adminUnpublishFreeMinecraftServer,
  adminDeleteFreeMinecraftServer,
} from "@/lib/actions-admin-freemc";

/**
 * Live running/player-count status for one row, fetched lazily on demand (a
 * button click), never automatically for every row on page load — see
 * app/admin/free-minecraft/page.tsx's header note on why the list view skips
 * a blocking N-SSH-calls status sweep.
 */
export function CheckStatusButton({ id }: { id: string }) {
  const [pending, start] = useTransition();
  const [result, setResult] = useState<string | null>(null);

  return (
    <div className="flex items-center gap-2">
      <button
        className="btn-ghost py-1 text-xs"
        disabled={pending}
        onClick={() =>
          start(async () => {
            const res = await adminGetFreeMinecraftStatus(id);
            if (!res.ok) {
              setResult(res.error);
              return;
            }
            if (!res.running) {
              setResult("asleep");
            } else if (res.players) {
              setResult(`up · ${res.players.online}/${res.players.max} players`);
            } else {
              setResult("up · booting");
            }
          })
        }
      >
        {pending ? "Checking…" : "Check status"}
      </button>
      {result && <span className="text-xs text-slate-400">{result}</span>}
    </div>
  );
}

export function UnpublishButton({ id, isPublic }: { id: string; isPublic: boolean }) {
  const [pending, start] = useTransition();
  if (!isPublic) return null;

  return (
    <button
      className="btn-secondary py-1 text-xs"
      disabled={pending}
      title="Pull this server's public directory listing"
      onClick={() => {
        if (!confirm("Pull this server's public listing? It stays online, just no longer publicly discoverable.")) return;
        start(async () => {
          const res = await adminUnpublishFreeMinecraftServer(id);
          if (res?.error) alert(res.error);
        });
      }}
    >
      {pending ? "Unpublishing…" : "Unpublish"}
    </button>
  );
}

export function DeleteFreeServerButton({ id, subdomain }: { id: string; subdomain: string }) {
  const [pending, start] = useTransition();

  return (
    <button
      className="btn-danger py-1 text-xs"
      disabled={pending}
      onClick={() => {
        if (
          !confirm(
            `Delete "${subdomain}"'s free Minecraft server? This removes the container and ALL its world data on freemc-host — this cannot be undone.`
          )
        )
          return;
        start(async () => {
          const res = await adminDeleteFreeMinecraftServer(id);
          if (res?.error) alert(res.error);
        });
      }}
    >
      {pending ? "Deleting…" : "Delete"}
    </button>
  );
}

import Link from "next/link";
import { requireArea } from "@/lib/rbac";
import { db } from "@/lib/db";
import { getSetting } from "@/lib/settings";
import { FREEMC_PRESETS } from "@/lib/free-minecraft-control";
import { PageHeader, StatCard, StatusDot, Badge, EmptyState, timeAgo } from "@/components/ui/primitives";
import { CheckStatusButton, UnpublishButton, DeleteFreeServerButton } from "@/components/admin/FreeMinecraftControls";

export const dynamic = "force-dynamic";

// Sane cap so this page never has to paginate a runaway free-tier list — the
// product also enforces a `free_minecraft_max_concurrent` total-server cap
// (see lib/actions-free-minecraft.ts), so today's real count is far below
// this. If it's ever hit, the header below says so explicitly rather than
// silently truncating.
const LIST_CAP = 100;

export default async function AdminFreeMinecraft() {
  await requireArea("fleet");

  const domain = await getSetting("free_minecraft_domain", "play.nxeon.cloud");

  const [rows, totalCount, readyCount, publicCount] = await Promise.all([
    db.freeMinecraftServer.findMany({
      take: LIST_CAP,
      orderBy: { createdAt: "desc" },
      include: { user: { select: { id: true, name: true, email: true } } },
    }),
    db.freeMinecraftServer.count(),
    db.freeMinecraftServer.count({ where: { status: "READY" } }),
    db.freeMinecraftServer.count({ where: { isPublic: true } }),
  ]);

  const truncated = totalCount > LIST_CAP;

  return (
    <div className="space-y-6">
      <PageHeader
        title="Free Minecraft"
        sub="Every free-tier Docker Minecraft server across all accounts, running on the dedicated freemc-host box."
      />

      <div className="grid gap-4 sm:grid-cols-3">
        <StatCard label="Total free servers" value={String(totalCount)} />
        <StatCard label="Ready" value={`${readyCount} / ${totalCount}`} />
        <StatCard label="Publicly listed" value={String(publicCount)} />
      </div>

      {/* Deliberate design choice, not an oversight: live running/player-count
          status is NOT fetched for every row here. Doing that as N sequential
          SSH calls to freemc-host on every page load would be slow and fragile
          as this list grows — instead each row gets an on-demand "Check
          status" button (components/admin/FreeMinecraftControls.tsx) that
          fetches just that one server's live state via a single SSH round
          trip when clicked. */}
      <div className="card p-4 text-xs text-slate-400">
        Live running/player status is not loaded automatically — use each row&apos;s <strong>Check status</strong> button
        to query it on demand (one SSH round trip to freemc-host per click).
      </div>

      <div>
        <h2 className="section-label mb-2">
          Free servers
          {truncated && (
            <span className="ml-2 font-normal normal-case text-amber-400">
              — showing the {LIST_CAP} most recent of {totalCount}
            </span>
          )}
        </h2>
        {rows.length === 0 ? (
          <EmptyState
            title="No free Minecraft servers yet"
            sub="Once a customer creates one from their dashboard, it'll show up here."
          />
        ) : (
          <div className="card overflow-x-auto p-0">
            <table className="table-shell">
              <thead>
                <tr>
                  <th>Owner</th>
                  <th>Server</th>
                  <th>Connect address</th>
                  <th>Preset</th>
                  <th>Status</th>
                  <th>Listing</th>
                  <th>Created</th>
                  <th>Live status</th>
                  <th className="text-right">Actions</th>
                </tr>
              </thead>
              <tbody>
                {rows.map((s) => {
                  const preset = FREEMC_PRESETS[s.preset];
                  return (
                    <tr key={s.id}>
                      <td>
                        <Link href={`/admin/users/${s.user.id}`} className="font-medium hover:text-brand-300">
                          {s.user.name || s.user.email}
                        </Link>
                        <span className="ml-2 text-xs text-slate-500">{s.user.email}</span>
                      </td>
                      <td>
                        <span className="font-medium">{s.name || s.subdomain}</span>
                      </td>
                      <td className="font-mono text-xs text-slate-400">
                        {s.subdomain}.{domain}
                      </td>
                      <td>
                        <Badge tone="brand">{preset?.label ?? s.preset}</Badge>
                      </td>
                      <td>
                        <StatusDot status={s.status} />
                      </td>
                      <td>{s.isPublic ? <Badge tone="green">public</Badge> : <Badge tone="slate">private</Badge>}</td>
                      <td className="text-xs text-slate-400">{timeAgo(s.createdAt)}</td>
                      <td>
                        <CheckStatusButton id={s.id} />
                      </td>
                      <td className="text-right">
                        <div className="flex items-center justify-end gap-2">
                          <UnpublishButton id={s.id} isPublic={s.isPublic} />
                          <DeleteFreeServerButton id={s.id} subdomain={s.subdomain} />
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
}

